#include <array>
#include <cmath>
#include <format>
#include <iostream>
#include <numbers>
#include <string>

using Vec3 = std::array<double, 3>;
using Mat3 = std::array<Vec3, 3>;  // three rows

[[nodiscard]] Vec3 operator*(const Mat3& m, const Vec3& v) {
  Vec3 out{};
  for (int r = 0; r < 3; ++r) {
    out[r] = m[r][0] * v[0] + m[r][1] * v[1] + m[r][2] * v[2];
  }
  return out;
}

// Rotations about the fixed x, y and z axes, counterclockwise when the axis points at you.
[[nodiscard]] Mat3 rot_x(double a) {
  const double c = std::cos(a), s = std::sin(a);
  return {{{1, 0, 0}, {0, c, -s}, {0, s, c}}};
}
[[nodiscard]] Mat3 rot_y(double a) {
  const double c = std::cos(a), s = std::sin(a);
  return {{{c, 0, s}, {0, 1, 0}, {-s, 0, c}}};
}
[[nodiscard]] Mat3 rot_z(double a) {
  const double c = std::cos(a), s = std::sin(a);
  return {{{c, -s, 0}, {s, c, 0}, {0, 0, 1}}};
}

[[nodiscard]] double tidy(double v) { return std::round(v * 1000) / 1000 + 0.0; }  // prints -0.000 as 0.000

[[nodiscard]] std::string show(const Vec3& v) {
  return std::format("({:.3f}, {:.3f}, {:.3f})", tidy(v[0]), tidy(v[1]), tidy(v[2]));
}

int main() {
  constexpr double quarter = std::numbers::pi / 2;
  constexpr Vec3 nose{1, 0, 0};
  std::cout << "yaw, then pitch: " << show(rot_y(quarter) * (rot_z(quarter) * nose)) << '\n';
  std::cout << "pitch, then yaw: " << show(rot_z(quarter) * (rot_y(quarter) * nose)) << '\n';
}

#include <algorithm>
#include <array>
#include <cmath>
#include <format>
#include <iostream>
#include <numbers>
#include <string>

using Vec3 = std::array<double, 3>;

struct Quat {  // ROS order: the vector part x, y, z, then the scalar w
  double x, y, z, w;
};

struct Rpy {
  double roll, pitch, yaw;
};

// Hamilton product: a * b applies b first, then a.
[[nodiscard]] constexpr Quat operator*(const Quat& a, const Quat& b) {
  return {.x = a.w * b.x + a.x * b.w + a.y * b.z - a.z * b.y,
          .y = a.w * b.y - a.x * b.z + a.y * b.w + a.z * b.x,
          .z = a.w * b.z + a.x * b.y - a.y * b.x + a.z * b.w,
          .w = a.w * b.w - a.x * b.x - a.y * b.y - a.z * b.z};
}

[[nodiscard]] constexpr Quat operator-(const Quat& q) { return {.x = -q.x, .y = -q.y, .z = -q.z, .w = -q.w}; }

[[nodiscard]] constexpr Quat conjugate(const Quat& q) { return {.x = -q.x, .y = -q.y, .z = -q.z, .w = q.w}; }

[[nodiscard]] constexpr double dot(const Quat& a, const Quat& b) {
  return a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
}

// A rotation by `angle` radians about a unit axis.
[[nodiscard]] Quat from_axis_angle(const Vec3& axis, double angle) {
  const double s = std::sin(angle / 2);
  return {.x = axis[0] * s, .y = axis[1] * s, .z = axis[2] * s, .w = std::cos(angle / 2)};
}

// The ROS convention: roll about the fixed x axis, then pitch about fixed y, then yaw about fixed z.
[[nodiscard]] Quat from_rpy(const Rpy& a) {
  return from_axis_angle({0, 0, 1}, a.yaw) * from_axis_angle({0, 1, 0}, a.pitch) *
         from_axis_angle({1, 0, 0}, a.roll);
}

// v' = q v q*, with v written as a quaternion whose w is 0.
[[nodiscard]] constexpr Vec3 rotate(const Quat& q, const Vec3& v) {
  const Quat r = q * Quat{.x = v[0], .y = v[1], .z = v[2], .w = 0} * conjugate(q);
  return {r.x, r.y, r.z};
}

[[nodiscard]] double yaw_of(const Quat& q) {
  return std::atan2(2 * (q.w * q.z + q.x * q.y), 1 - 2 * (q.y * q.y + q.z * q.z));
}

// Spherical linear interpolation along the shorter arc, for t from 0 to 1.
[[nodiscard]] Quat slerp(const Quat& a, Quat b, double t) {
  double cos_half = dot(a, b);
  if (cos_half < 0) {  // -b is the same rotation as b, and closer to a
    b = -b;
    cos_half = -cos_half;
  }
  const double half = std::acos(std::min(cos_half, 1.0));
  if (half < 1e-9) {
    return a;
  }
  const double wa = std::sin((1 - t) * half) / std::sin(half);
  const double wb = std::sin(t * half) / std::sin(half);
  return {.x = wa * a.x + wb * b.x, .y = wa * a.y + wb * b.y, .z = wa * a.z + wb * b.z, .w = wa * a.w + wb * b.w};
}

[[nodiscard]] double tidy(double v) { return std::round(v * 1000) / 1000 + 0.0; }

[[nodiscard]] std::string show(const Vec3& v) {
  return std::format("({:.3f}, {:.3f}, {:.3f})", tidy(v[0]), tidy(v[1]), tidy(v[2]));
}

[[nodiscard]] std::string show(const Quat& q) {
  return std::format("(x {:.3f}, y {:.3f}, z {:.3f}, w {:.3f})", tidy(q.x), tidy(q.y), tidy(q.z), tidy(q.w));
}

int main() {
  constexpr double deg = std::numbers::pi / 180;
  constexpr Vec3 nose{1, 0, 0};

  const Quat left = from_rpy({.roll = 0, .pitch = 0, .yaw = 90 * deg});
  std::cout << "yaw 90:      " << show(left) << " turns the nose to " << show(rotate(left, nose)) << '\n';
  std::cout << "its negative " << show(-left) << " turns the nose to " << show(rotate(-left, nose)) << '\n';

  const Quat a = from_rpy({.roll = 0, .pitch = 0, .yaw = 170 * deg});
  const Quat b = from_rpy({.roll = 0, .pitch = 0, .yaw = -170 * deg});
  std::cout << std::format("halfway from 170 to -170: average of angles {:.1f}, slerp {:.1f}\n",
                           tidy((170.0 + -170.0) / 2), tidy(yaw_of(slerp(a, b, 0.5)) / deg));
}

#include <array>
#include <cmath>
#include <format>
#include <iostream>
#include <numbers>
#include <optional>

using Vec3 = std::array<double, 3>;

struct Quat {
  double x, y, z, w;
};

struct Rpy {
  double roll, pitch, yaw;
};

[[nodiscard]] constexpr Quat operator*(const Quat& a, const Quat& b) {
  return {.x = a.w * b.x + a.x * b.w + a.y * b.z - a.z * b.y,
          .y = a.w * b.y - a.x * b.z + a.y * b.w + a.z * b.x,
          .z = a.w * b.z + a.x * b.y - a.y * b.x + a.z * b.w,
          .w = a.w * b.w - a.x * b.x - a.y * b.y - a.z * b.z};
}

[[nodiscard]] Quat from_axis_angle(const Vec3& axis, double angle) {
  const double s = std::sin(angle / 2);
  return {.x = axis[0] * s, .y = axis[1] * s, .z = axis[2] * s, .w = std::cos(angle / 2)};
}

[[nodiscard]] Quat from_rpy(const Rpy& a) {
  return from_axis_angle({0, 0, 1}, a.yaw) * from_axis_angle({0, 1, 0}, a.pitch) *
         from_axis_angle({1, 0, 0}, a.roll);
}

[[nodiscard]] std::optional<Quat> normalized(const Quat& q) {
  const double norm = std::sqrt(q.x * q.x + q.y * q.y + q.z * q.z + q.w * q.w);
  if (norm < 1e-9) {
    return std::nullopt;  // no direction to scale back to
  }
  return Quat{.x = q.x / norm, .y = q.y / norm, .z = q.z / norm, .w = q.w / norm};
}

// q must be a unit quaternion. The pitch comes back in [-pi/2, pi/2].
[[nodiscard]] Rpy to_rpy(const Quat& q) {
  constexpr double pi = std::numbers::pi;
  const double sin_pitch = 2 * (q.w * q.y - q.z * q.x);
  if (std::abs(sin_pitch) > 1 - 1e-9) {
    // Gimbal lock: only yaw - roll (pitch +90, nose down) or yaw + roll (pitch -90, nose up) is defined.
    // Report all of it as yaw.
    const double yaw = std::remainder(2 * std::atan2(q.z, q.w), 2 * pi);
    return {.roll = 0, .pitch = std::copysign(pi / 2, sin_pitch), .yaw = yaw};
  }
  return {.roll = std::atan2(2 * (q.w * q.x + q.y * q.z), 1 - 2 * (q.x * q.x + q.y * q.y)),
          .pitch = std::asin(sin_pitch),
          .yaw = std::atan2(2 * (q.w * q.z + q.x * q.y), 1 - 2 * (q.y * q.y + q.z * q.z))};
}

[[nodiscard]] double tidy(double v) { return std::round(v * 1000) / 1000 + 0.0; }

int main() {
  constexpr double deg = std::numbers::pi / 180;
  constexpr std::array<Rpy, 4> cases{{{.roll = 10, .pitch = 20, .yaw = 30},
                                      {.roll = 0, .pitch = 0, .yaw = 179},
                                      {.roll = -45, .pitch = 60, .yaw = 135},
                                      {.roll = 10, .pitch = 90, .yaw = 20}}};
  for (const Rpy& c : cases) {
    const Rpy back = to_rpy(from_rpy({.roll = c.roll * deg, .pitch = c.pitch * deg, .yaw = c.yaw * deg}));
    std::cout << std::format("({:.0f}, {:.0f}, {:.0f}) -> ({:.3f}, {:.3f}, {:.3f})\n", c.roll, c.pitch, c.yaw,
                             tidy(back.roll / deg), tidy(back.pitch / deg), tidy(back.yaw / deg));
  }

  constexpr std::array<Quat, 4> given{{{.x = 0, .y = 0, .z = 0.383, .w = 0.924},
                                       {.x = 0, .y = 0, .z = -0.383, .w = -0.924},
                                       {.x = 0, .y = 0, .z = 0.7, .w = 0.7},
                                       {.x = 0, .y = 0, .z = 0, .w = 0}}};
  for (const Quat& q : given) {
    if (const std::optional<Quat> unit = normalized(q)) {
      std::cout << std::format("z {:.3f}, w {:.3f}: yaw {:.1f}\n", q.z, q.w, tidy(to_rpy(*unit).yaw / deg));
    } else {
      std::cout << std::format("z {:.3f}, w {:.3f}: not a rotation\n", q.z, q.w);
    }
  }
}

#include <array>
#include <cmath>
#include <format>
#include <iostream>
#include <numbers>

// The order of the 6 x 6 matrix in geometry_msgs/msg/PoseWithCovariance.
enum class Axis { x, y, z, rot_x, rot_y, rot_z };

// Wraps the message's float64[36], which C++ sees as std::array<double, 36>, row by row.
class PoseCovariance {
 public:
  [[nodiscard]] static constexpr int index(Axis row, Axis col) {
    return 6 * static_cast<int>(row) + static_cast<int>(col);
  }
  [[nodiscard]] double at(Axis row, Axis col) const { return values_[index(row, col)]; }
  void set(Axis row, Axis col, double v) {  // keeps the matrix symmetric
    values_[index(row, col)] = v;
    values_[index(col, row)] = v;
  }

 private:
  std::array<double, 36> values_{};
};

struct Ellipse {
  double major_m, minor_m, angle_rad;
};

// The x-y ellipse at `scale` standard deviations: its semi-axes and the direction of the long one.
[[nodiscard]] Ellipse xy_ellipse(const PoseCovariance& c, double scale) {
  const double sxx = c.at(Axis::x, Axis::x), syy = c.at(Axis::y, Axis::y), sxy = c.at(Axis::x, Axis::y);
  const double mid = (sxx + syy) / 2;
  const double half_gap = std::hypot((sxx - syy) / 2, sxy);  // the eigenvalues are mid +- half_gap
  return {.major_m = scale * std::sqrt(mid + half_gap),
          .minor_m = scale * std::sqrt(mid - half_gap),
          .angle_rad = std::atan2(2 * sxy, sxx - syy) / 2};
}

int main() {
  constexpr double deg = std::numbers::pi / 180;
  PoseCovariance odom;
  odom.set(Axis::x, Axis::x, 0.04);            // m^2
  odom.set(Axis::y, Axis::y, 0.01);            // m^2
  odom.set(Axis::x, Axis::y, 0.012);           // m^2, written at both mirrored indices
  odom.set(Axis::rot_z, Axis::rot_z, 0.0025);  // rad^2

  const double sx = std::sqrt(odom.at(Axis::x, Axis::x));
  const double sy = std::sqrt(odom.at(Axis::y, Axis::y));
  const double syaw = std::sqrt(odom.at(Axis::rot_z, Axis::rot_z));
  std::cout << std::format("x-y at indices {} and {}, yaw variance at index {}\n",
                           PoseCovariance::index(Axis::x, Axis::y), PoseCovariance::index(Axis::y, Axis::x),
                           PoseCovariance::index(Axis::rot_z, Axis::rot_z));
  std::cout << std::format("sigma x {:.3f} m, sigma y {:.3f} m, sigma yaw {:.3f} rad ({:.2f} deg)\n", sx, sy, syaw,
                           syaw / deg);
  std::cout << std::format("correlation of x and y: {:.2f}\n", odom.at(Axis::x, Axis::y) / (sx * sy));

  const double one_sigma = 1 - std::exp(-0.5);            // share inside the 1-sigma ellipse in two dimensions
  const double scale_95 = std::sqrt(-2 * std::log(0.05));  // 2.448 standard deviations hold 95 % in two dimensions
  const Ellipse e = xy_ellipse(odom, scale_95);
  std::cout << std::format("inside the 1-sigma ellipse: {:.1f} %\n", 100 * one_sigma);
  std::cout << std::format("95 % ellipse: {:.3f} m by {:.3f} m, long axis at {:.1f} deg\n", e.major_m, e.minor_m,
                           e.angle_rad / deg);
  for (const double metres : {1.0, 10.0, 50.0}) {
    std::cout << std::format("sideways sigma after {:>4.0f} m straight: {:.3f} m\n", metres, metres * syaw);
  }
}

#include <array>
#include <cmath>
#include <format>
#include <iostream>
#include <numbers>
#include <optional>

using Vec3 = std::array<double, 3>;

struct Quat {
  double x, y, z, w;
};

struct Rpy {
  double roll, pitch, yaw;
};

[[nodiscard]] Quat from_axis_angle(const Vec3& axis, double angle) {
  const double s = std::sin(angle / 2);
  return {.x = axis[0] * s, .y = axis[1] * s, .z = axis[2] * s, .w = std::cos(angle / 2)};
}

[[nodiscard]] double norm(const Quat& q) { return std::sqrt(q.x * q.x + q.y * q.y + q.z * q.z + q.w * q.w); }

[[nodiscard]] std::optional<Quat> normalized(const Quat& q) {
  const double n = norm(q);
  if (n < 1e-9) {
    return std::nullopt;
  }
  return Quat{.x = q.x / n, .y = q.y / n, .z = q.z / n, .w = q.w / n};
}

[[nodiscard]] Rpy to_rpy(const Quat& q) {
  constexpr double pi = std::numbers::pi;
  const double sin_pitch = 2 * (q.w * q.y - q.z * q.x);
  if (std::abs(sin_pitch) > 1 - 1e-9) {
    return {.roll = 0, .pitch = std::copysign(pi / 2, sin_pitch),
            .yaw = std::remainder(2 * std::atan2(q.z, q.w), 2 * pi)};
  }
  return {.roll = std::atan2(2 * (q.w * q.x + q.y * q.z), 1 - 2 * (q.x * q.x + q.y * q.y)),
          .pitch = std::asin(sin_pitch),
          .yaw = std::atan2(2 * (q.w * q.z + q.x * q.y), 1 - 2 * (q.y * q.y + q.z * q.z))};
}

// The mean of two readings, component by component.
[[nodiscard]] Quat naive_mean(const Quat& a, const Quat& b) {
  return {.x = (a.x + b.x) / 2, .y = (a.y + b.y) / 2, .z = (a.z + b.z) / 2, .w = (a.w + b.w) / 2};
}

[[nodiscard]] double tidy(double v) { return std::round(v * 1000) / 1000 + 0.0; }

int main() {
  constexpr double deg = std::numbers::pi / 180;
  std::cout << "tilting about y past vertical:\n";
  for (const double tilt : {88.0, 89.0, 90.0, 91.0, 92.0}) {
    const Quat q = from_axis_angle({0, 1, 0}, tilt * deg);
    const Rpy a = to_rpy(q);
    std::cout << std::format("  {:.0f} deg: y {:.3f}, w {:.3f} -> roll {:.1f}, pitch {:.1f}, yaw {:.1f}\n", tilt,
                             tidy(q.y), tidy(q.w), tidy(a.roll / deg), tidy(a.pitch / deg), tidy(a.yaw / deg));
  }

  const Quat east = from_axis_angle({0, 0, 1}, 90 * deg);
  const Quat same_east{.x = -east.x, .y = -east.y, .z = -east.z, .w = -east.w};
  const Quat north = from_axis_angle({0, 0, 1}, 0);
  const Quat mean = naive_mean(east, north);
  std::cout << std::format("mean of yaw 90 and yaw 0: norm {:.3f}, squared {:.3f}\n", norm(mean),
                           norm(mean) * norm(mean));
  std::cout << std::format("  normalized: yaw {:.1f}\n", tidy(to_rpy(normalized(mean).value()).yaw / deg));
  const Quat zero = naive_mean(east, same_east);
  std::cout << std::format("mean of q and -q: norm {:.3f}, normalized has a value: {}\n", norm(zero),
                           normalized(zero).has_value());
}
